#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn dmacfg_30026() {
        assert_eq!(dmacfg::d1::get(0x30026), 6);
        assert_eq!(dmacfg::d2::get(0x30026), 2);
        assert_eq!(dmacfg::d3::get(0x30026), 0);
        assert_eq!(dmacfg::wr_ctrl::get(0x30026), 0);
        assert_eq!(dmacfg::fix_rxdc::get(0x30026), 0);
        assert_eq!(dmacfg::fix_eop::get(0x30026), 0);
        assert_eq!(dmacfg::fix_intr::get(0x30026), 0);
        assert_eq!(dmacfg::fix_timeout::get(0x30026), 3);
    }

    #[test]
    fn dmacfg_3e026() {
        assert_eq!(dmacfg::d1::get(0x3e026), 6);
        assert_eq!(dmacfg::d2::get(0x3e026), 2);
        assert_eq!(dmacfg::d3::get(0x3e026), 0);
        assert_eq!(dmacfg::wr_ctrl::get(0x3e026), 0);
        assert_eq!(dmacfg::fix_rxdc::get(0x3e026), 1);
        assert_eq!(dmacfg::fix_eop::get(0x3e026), 1);
        assert_eq!(dmacfg::fix_intr::get(0x3e026), 1);
        assert_eq!(dmacfg::fix_timeout::get(0x3e026), 3);
    }

    #[test]
    fn piocfg_161() {
        assert_eq!(piocfg::p1::get(0x161), 1);
        assert_eq!(piocfg::p2::get(0x161), 6);
        assert_eq!(piocfg::p3::get(0x161), 1);
        assert_eq!(piocfg::fifo_ram_test::get(0x161), 0);
    }
}
